const positions = ["bottom-spaces-toolbar", "bottom-today-pane"];

for (const position of positions) {
  this.classList.toggle(position, notification.position === position);
}

if (!positions.includes(notification.position)) {
  this.classList.add("bottom-spaces-toolbar");
}

add_task(function test_notificationPositionNull() {
  const data = getData("test");

  notification.setNotificationData({
    ...data,
    position: null,
  });

  Assert.ok(
    notification.classList.contains("bottom-spaces-toolbar"),
    "has correct position class"
  );
});

